enum Op: Equatable { case get(String), put(String, Int), log(String) }

func run(_ op: Op, store: inout [String: Int]) -> Int {
    switch op {
    case .get(let k):        return store[k] ?? 0
    case .put(let k, let v): store[k] = v; return v
    case .log(let m):        print(m); return 0
    }
}
